{"html":"<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<title>从素材到故事</title>
<style>
  html,body{margin:0;padding:0;overflow:hidden;background:#ffffff;}
  #stage{position:relative;width:1280px;height:720px;background:#ffffff;overflow:hidden;
    font-family:'PingFang SC','Arial',sans-serif;}
  .abs{position:absolute;}
  .label{font-size:30px;color:#1B4DFF;letter-spacing:2px;font-weight:500;white-space:nowrap;}
  .hint{font-size:22px;color:#7C97FF;letter-spacing:1px;white-space:nowrap;}
  .prevTitle{font-size:40px;color:#1B4DFF;letter-spacing:4px;font-weight:600;white-space:nowrap;}
  .sub{font-size:22px;color:#5B78E6;letter-spacing:2px;white-space:nowrap;}
</style>
</head>
<body>
<div id="stage">
  <div id="labelsWrap" class="abs"></div>
  <div id="hintsWrap" class="abs"></div>
  <div id="squaresWrap" class="abs"></div>
  <svg id="lines" class="abs" width="1280" height="720" style="left:0;top:0;"></svg>
  <div id="previewBox" class="abs"></div>
  <div id="prevText" class="abs prevTitle" style="opacity:0;">故事预览</div>
  <div id="prevSub" class="abs sub" style="opacity:0;">素材 → 镜头 → 成片</div>
  <div id="progressLine" class="abs" style="opacity:0;height:3px;background:#1B4DFF;border-radius:2px;"></div>
  <svg id="corners" class="abs" width="1280" height="720" style="left:0;top:0;pointer-events:none;"></svg>
</div>
<script>
(function(){
  var stage = document.getElementById('stage');

  var sqSize = 56;
  var sqGapX = 26, sqGapY = 26;
  var baseX = 150, baseY = 250;
  var squarePositions = [];
  for(var r=0;r<3;r++){
    for(var c=0;c<2;c++){
      squarePositions.push({ x: baseX + c*(sqSize+sqGapX), y: baseY + r*(sqSize+sqGapY) });
    }
  }

  var branchNode = [
    {x: 780, y: 200},
    {x: 800, y: 360},
    {x: 780, y: 520}
  ];

  var hintTexts = [
    {t:'镜头顺序', x: branchNode[0].x+34, y: branchNode[0].y-14},
    {t:'画面组合', x: branchNode[1].x+34, y: branchNode[1].y-14},
    {t:'节奏点',   x: branchNode[2].x+34, y: branchNode[2].y-14}
  ];

  var box = {x: 860, y: 240, w: 320, h: 240};

  var labelPos = [
    {t:'选取', x: 400, y: 298},
    {t:'编排', x: 400, y: 354},
    {t:'成片', x: 400, y: 410}
  ];

  var labelsWrap = document.getElementById('labelsWrap');
  var hintsWrap = document.getElementById('hintsWrap');
  var squaresWrap = document.getElementById('squaresWrap');

  var labelEls = [];
  labelPos.forEach(function(p){
    var d = document.createElement('div');
    d.className = 'abs label';
    d.textContent = p.t;
    d.style.left = p.x+'px';
    d.style.top = p.y+'px';
    d.style.opacity = '0';
    labelsWrap.appendChild(d);
    labelEls.push(d);
  });

  var hintEls = [];
  hintTexts.forEach(function(p){
    var d = document.createElement('div');
    d.className = 'abs hint';
    d.textContent = p.t;
    d.style.left = p.x+'px';
    d.style.top = p.y+'px';
    d.style.opacity = '0';
    hintsWrap.appendChild(d);
    hintEls.push(d);
  });

  var squareEls = [];
  squarePositions.forEach(function(p){
    var d = document.createElement('div');
    d.className = 'abs';
    d.style.width = sqSize+'px';
    d.style.height = sqSize+'px';
    d.style.boxSizing = 'border-box';
    d.style.border = '2.5px solid #1B4DFF';
    d.style.borderRadius = '4px';
    d.style.opacity = '0';
    d.style.left = '0px';
    d.style.top = '0px';
    squaresWrap.appendChild(d);
    squareEls.push(d);
  });

  var svg = document.getElementById('lines');
  var NS = 'http://www.w3.org/2000/svg';

  var branchPaths = branchNode.map(function(){
    var path = document.createElementNS(NS,'path');
    path.setAttribute('fill','none');
    path.setAttribute('stroke','#9FB6FF');
    path.setAttribute('stroke-width','2');
    path.setAttribute('stroke-linecap','round');
    svg.appendChild(path);
    return path;
  });

  var nodeCircles = branchNode.map(function(n){
    var c = document.createElementNS(NS,'circle');
    c.setAttribute('cx', n.x);
    c.setAttribute('cy', n.y);
    c.setAttribute('r', 6);
    c.setAttribute('fill','#1B4DFF');
    c.setAttribute('opacity','0');
    svg.appendChild(c);
    return c;
  });

  var mergePaths = branchNode.map(function(){
    var p = document.createElementNS(NS,'path');
    p.setAttribute('fill','none');
    p.setAttribute('stroke','#C7D5FF');
    p.setAttribute('stroke-width','2');
    p.setAttribute('stroke-linecap','round');
    svg.appendChild(p);
    return p;
  });

  var previewBox = document.getElementById('previewBox');
  previewBox.style.left = box.x+'px';
  previewBox.style.top = box.y+'px';
  previewBox.style.width = box.w+'px';
  previewBox.style.height = box.h+'px';
  previewBox.style.boxSizing = 'border-box';
  previewBox.style.borderRadius = '6px';
  previewBox.style.background = 'rgba(247,249,255,0)';

  var edgeDefs = [
    {x1:0, y1:0, x2:box.w, y2:0, delay:4.0},
    {x1:box.w, y1:0, x2:box.w, y2:box.h, delay:4.25},
    {x1:box.w, y1:box.h, x2:0, y2:box.h, delay:4.5},
    {x1:0, y1:box.h, x2:0, y2:0, delay:4.75}
  ];
  var edgeEls = edgeDefs.map(function(){
    var d = document.createElement('div');
    d.className = 'abs';
    d.style.background = '#1B4DFF';
    d.style.borderRadius = '1px';
    d.style.opacity = '0';
    previewBox.appendChild(d);
    return d;
  });

  var prevText = document.getElementById('prevText');
  var prevSub = document.getElementById('prevSub');
  var progressLine = document.getElementById('progressLine');

  var cornersSvg = document.getElementById('corners');
  var cornerEls = [];
  var cornerGeo = [
    {x:box.x-6, y:box.y-6, hx:1, hy:1},
    {x:box.x+box.w+6, y:box.y-6, hx:-1, hy:1},
    {x:box.x-6, y:box.y+box.h+6, hx:1, hy:-1},
    {x:box.x+box.w+6, y:box.y+box.h+6, hx:-1, hy:-1}
  ];
  cornerGeo.forEach(function(g){
    var p = document.createElementNS(NS,'path');
    var len = 22;
    var d = 'M '+(g.x+g.hx*len)+' '+g.y+' L '+g.x+' '+g.y+' L '+g.x+' '+(g.y+g.hy*len);
    p.setAttribute('d', d);
    p.setAttribute('fill','none');
    p.setAttribute('stroke','#1B4DFF');
    p.setAttribute('stroke-width','3');
    p.setAttribute('stroke-linecap','round');
    p.setAttribute('stroke-linejoin','round');
    p.setAttribute('opacity','0');
    cornersSvg.appendChild(p);
    cornerEls.push(p);
  });

  function clamp(v,a,b){ return v<a?a:(v>b?b:v); }
  function easeOut(t){ t=clamp(t,0,1); return 1-Math.pow(1-t,3); }
  function easeInOut(t){ t=clamp(t,0,1); return t<0.5? 2*t*t : 1-Math.pow(-2*t+2,2)/2; }
  function seg(t, a, b){ if(b<=a) return t>=b?1:0; return clamp((t-a)/(b-a), 0, 1); }

  function squareTarget(i){
    var branch = Math.floor(i/2);
    var n = branchNode[branch];
    var offsetIndex = i%2;
    return {
      x: n.x - sqSize/2 + (offsetIndex===0? -18: 18),
      y: n.y - sqSize/2
    };
  }

  window.renderAt = function(t){
    t = Math.max(0, Math.min(10, t));

    // 三行文字 0.0–4.0
    var labelAlpha = 1;
    if(t > 3.7){ labelAlpha = 1 - easeOut(seg(t,3.7,4.0)); }
    labelEls.forEach(function(el,i){
      var appear = easeOut(seg(t, 0.05 + i*0.10, 0.45 + i*0.10));
      var a = labelAlpha * appear;
      el.style.opacity = a.toFixed(3);
      el.style.transform = 'translateX(' + ((1-appear)*(-16)) + 'px)';
    });

    // 方块
    squareEls.forEach(function(el,i){
      var ap = easeOut(seg(t, 0.05 + i*0.08, 0.5 + i*0.08));
      var startP = squarePositions[i];
      var mv = seg(t, 1.5 + (i%2)*0.12 + Math.floor(i/2)*0.08, 3.1 + (i%2)*0.12 + Math.floor(i/2)*0.08);
      var mve = easeInOut(mv);
      var target = squareTarget(i);
      var cx = startP.x + (target.x - startP.x) * mve;
      var cy = startP.y + (target.y - startP.y) * mve;
      var fadeOut = 1 - easeOut(seg(t, 4.0, 4.6));
      var endFade = 1 - easeOut(seg(t, 8.8, 9.4));
      el.style.opacity = (ap * fadeOut * endFade).toFixed(3);
      el.style.left = cx.toFixed(2)+'px';
      el.style.top = cy.toFixed(2)+'px';
      var sc = 0.85 + 0.15*ap;
      el.style.transform = 'scale('+sc.toFixed(3)+')';
    });

    // 分支曲线
    var branchAlpha = 1;
    if(t < 1.7) branchAlpha = easeOut(seg(t,1.5,1.9));
    if(t > 3.8) branchAlpha = 1 - easeOut(seg(t,3.8,4.3));
    if(t > 8.8) branchAlpha *= 1 - easeOut(seg(t,8.8,9.4));

    branchPaths.forEach(function(p, idx){
      var n = branchNode[idx];
      var sx = baseX + 2*(sqSize+sqGapX) - 6;
      var sy = baseY + idx*(sqSize+sqGapY) + sqSize/2;
      var ex = n.x - 8, ey = n.y;
      var mx = (sx+ex)/2 + 40;
      var d = 'M '+sx+' '+sy+' C '+mx+' '+sy+', '+mx+' '+ey+', '+ex+' '+ey;
      p.setAttribute('d', d);
      var draw = easeOut(seg(t, 1.6 + idx*0.12, 2.4 + idx*0.12));
      p.setAttribute('stroke-dasharray', '600');
      p.setAttribute('stroke-dashoffset', (600*(1-draw)).toFixed(1));
      p.setAttribute('opacity', branchAlpha.toFixed(3));
    });

    // 节点圆点
    nodeCircles.forEach(function(c, idx){
      var a = easeOut(seg(t, 2.2 + idx*0.15, 2.7 + idx*0.15));
      if(t > 3.8) a *= 1 - easeOut(seg(t,3.8,4.2));
      if(t > 8.8) a *= 1 - easeOut(seg(t,8.8,9.4));
      c.setAttribute('opacity', a.toFixed(3));
      var pulse = 1;
      if(t>2.7 && t<4.0){ pulse = 1 + 0.12*Math.sin((t-2.7)*6); }
      c.setAttribute('r', (6*pulse).toFixed(2));
    });

    // 提示文字
    hintEls.forEach(function(el, idx){
      var a = easeOut(seg(t, 2.3 + idx*0.15, 2.9 + idx*0.15));
      if(t > 3.7) a *= 1 - easeOut(seg(t,3.7,4.1));
      if(t > 8.8) a *= 1 - easeOut(seg(t,8.8,9.4));
      el.style.opacity = a.toFixed(3);
      el.style.transform = 'translateX(' + ((1-a)*10) + 'px)';
    });

    // 汇合曲线
    var mergeAlpha = 0;
    if(t >= 4.0) mergeAlpha = easeOut(seg(t,4.0,4.6));
    if(t > 5.4) mergeAlpha *= 1 - easeOut(seg(t,5.4,6.3));

    mergePaths.forEach(function(p, idx){
      var n = branchNode[idx];
      var sx = n.x + 8, sy = n.y;
      var ex = box.x - 6, ey = box.y + box.h*0.5;
      var mx = (sx+ex)/2 + 20;
      var d = 'M '+sx+' '+sy+' C '+mx+' '+sy+', '+mx+' '+ey+', '+ex+' '+ey;
      p.setAttribute('d', d);
      var draw = easeOut(seg(t, 4.0 + idx*0.1, 4.8 + idx*0.1));
      p.setAttribute('stroke-dasharray', '400');
      p.setAttribute('stroke-dashoffset', (400*(1-draw)).toFixed(1));
      p.setAttribute('opacity', mergeAlpha.toFixed(3));
    });

    // 预览框四条边
    edgeDefs.forEach(function(e, idx){
      var el = edgeEls[idx];
      var p = easeOut(seg(t, e.delay, e.delay+0.55));
      var isHoriz = (e.y1===e.y2);
      var thick = 3;
      if(isHoriz){
        el.style.height = thick+'px';
        el.style.top = (e.y1 - thick/2)+'px';
        el.style.width = (box.w*p).toFixed(1)+'px';
        el.style.left = (e.x1===0 ? 0 : (box.w - box.w*p)) + 'px';
      } else {
        el.style.width = thick+'px';
        el.style.left = (e.x1 - thick/2)+'px';
        el.style.height = (box.h*p).toFixed(1)+'px';
        el.style.top = (e.y1===0 ? 0 : (box.h - box.h*p)) + 'px';
      }
      el.style.opacity = p>0 ? '1' : '0';
    });

    // 故事预览
    var titleA = easeOut(seg(t, 4.35, 4.95));
    prevText.style.opacity = titleA.toFixed(3);
    prevText.style.left = (box.x + box.w/2)+'px';
    prevText.style.top = (box.y + box.h/2 - 46)+'px';
    prevText.style.transform = 'translateX(-50%)';

    // 副标题
    var subA = easeOut(seg(t,4.8,5.3));
    if(t > 8.0) subA *= 1 - easeOut(seg(t,8.0,8.5));
    prevSub.style.opacity = subA.toFixed(3);
    prevSub.style.left = (box.x + box.w/2)+'px';
    prevSub.style.top = (box.y + box.h/2 + 22)+'px';
    prevSub.style.transform = 'translateX(-50%)';

    // 进度线
    var plA = easeOut(seg(t, 7.0, 7.6));
    plA *= 1 - easeOut(seg(t, 9.3, 9.7));
    progressLine.style.opacity = plA.toFixed(3);
    var plW = 220 * easeInOut(seg(t, 7.0, 8.0));
    progressLine.style.width = plW.toFixed(1)+'px';
    progressLine.style.left = baseX+'px';
    progressLine.style.top = (baseY + (3*(sqSize+sqGapY)-sqGapY)/2 - 1)+'px';

    // 取景角标
    var cornerA = easeOut(seg(t,7.2,7.7));
    if(t > 8.3) cornerA *= 1 - easeOut(seg(t,8.3,8.9));
    cornerEls.forEach(function(c){
      c.setAttribute('opacity', cornerA.toFixed(3));
      var s = 1;
      if(t>7.7 && t<8.3){ s = 1 + 0.08*Math.sin((t-7.7)*7); }
      c.setAttribute('stroke-width', (3*s).toFixed(2));
    });

    // 预览框背景
    var boxBgA = easeOut(seg(t,4.2,5.2));
    previewBox.style.background = 'rgba(247,249,255,'+(0.9*boxBgA).toFixed(3)+')';

    // 结尾保持稳定，不回退文字
    if(t > 9.5){
      prevText.style.opacity = titleA.toFixed(3);
    }
  };

  window.renderAt(0);
})();
</script>
</body>
</html>","design_notes":"两处修复：一是去掉所有依赖真实时钟与正弦脉冲的残留写法之外的非确定性来源——所有视觉属性（opacity、位置、线宽、半径、背景色）均只由 t 经纯函数计算，删除了末段对 prevText.opacity 的递归式改写，改为一次性确定值，保证同一 t 重复采样完全一致。二是重排文字垂直基线，将「故事预览」上移至框内中心上方、副标题放置于中心下方，与 22px/40px 字号配合，避免文字重叠并保证框内留白。布局沿用原稿三支流与预览框，视觉层次保持：左侧 2×3 空心方块阵列→三支曲线→节点与提示→汇合到右侧预览框取景角标，色彩仍以 #1B4DFF 与浅蓝线框为主，白底极简。"}
